# P5 Amendment D 鈥?Autonomous Authority Bridge V1

CANONICAL_ID=P5_AMENDMENT_D_AUTONOMOUS_AUTHORITY_BRIDGE_V1

STATUS=PREPARED_UNREGISTERED

REOPEN_TRIGGER=PART_XII_TRIGGER_3_GENUINELY_AMENDMENT_CLASS_AUTHORITY_CHANGE

SCIENTIFIC_ESTIMAND_RULE_CHANGES=0

SCIENTIFIC_ADJUDICATION_RULE_CHANGES=0

AUTHORITY_GOVERNANCE_RULE_CHANGES=1

## 1. Scope and activation order

This amendment changes only the authorization procedure for one bounded P3 launch chain. It creates no authority while PREPARED_UNREGISTERED.

Exact frozen Amendment C MUST first be registered and APPLIED by a direct human-owner action under the pre-D interactive path. Only after C is APPLIED may exact Amendment D be registered and APPLIED by a distinct direct human-owner action. D cannot authorize, register, replace, bootstrap, or retroactively validate C. D_CAN_AUTHORIZE_C=NO.

The only permitted order is:

1. exact C, direct-owner, APPLIED;
2. exact D, direct-owner, APPLIED;
3. one owner-signed bounded root delegation registered;
4. exact A, then exact B, as two distinct delegated registration events;
5. exact T1-first information-order policy;
6. T1 child authority, execution, and seal;
7. Wave-1 child authority, all 174 frozen candidates, and seal;
8. STOP.

-- P5 direct-repair authority schema v2 -> v3.
-- Production prerequisite: every v2 authority table is empty. Fail closed
-- rather than rewriting any authority-bearing row.
CREATE TEMP TABLE _p5_v3_empty_gate(n INTEGER NOT NULL CHECK(n=0)) STRICT;
INSERT INTO _p5_v3_empty_gate SELECT
 (SELECT count(*) FROM authority_proposals)+
 (SELECT count(*) FROM authority_transitions)+
 (SELECT count(*) FROM logical_trials)+
 (SELECT count(*) FROM trial_attempts)+
 (SELECT count(*) FROM owner_conditional_delegations)+
 (SELECT count(*) FROM delegation_redemptions)+
 (SELECT count(*) FROM owner_delegation_revocations)+
 (SELECT count(*) FROM amendment_registrations);
DROP TABLE _p5_v3_empty_gate;

DROP TABLE trial_attempts;
DROP TABLE logical_trials;
DROP TABLE delegation_redemptions;
DROP TABLE owner_delegation_revocations;
DROP TABLE owner_conditional_delegations;
